+import { buildRoster } from './roster.js';
+import { positiveInteger } from '../lib/validation.js';
+
+export function summarizeAttendance(event, signups) {
+  const capacity = positiveInteger(event?.capacity);
+  const attendees = buildRoster(signups).length;
+  return {
+    confirmed: Math.min(attendees, capacity),
+    remaining: Math.max(capacity - attendees, 0),
+    waitlisted: Math.max(attendees - capacity, 0),
+  };
+}

